drop table if exists kanji_info cascade;
create table kanji_info
(
    kanji           text    not null
        primary key,
    radical         text    not null,
    radvar          text,
    type            text,
    regular_on      text,
    regular_kun     text,
    onyomi          text,
    kunyomi         text,
    nanori          text,
    strokes         integer not null,
    grade           text    not null,
    jlpt            text,
    kanken          text,
    frequency       integer,
    meaning         text    not null,
    compact_meaning text,
    elements text,
    kanji_parts text,
    part_of text
);

